create extension if not exists pgcrypto;
do $$ begin create type user_role as enum ('super_admin','president','vice_president','executive_secretary','treasurer','auditor','cabinet_secretary','officer','student'); exception when duplicate_object then null; end $$;
create table if not exists departments(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,description text,created_at timestamptz not null default now());
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,role user_role not null default 'student',department_id uuid references departments(id),position text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists tasks(id uuid primary key default gen_random_uuid(),title text not null,description text,status text not null default 'pending',priority text not null default 'normal',assigned_to uuid references profiles(id),due_date date,created_by uuid references profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists activities(id uuid primary key default gen_random_uuid(),title text not null,description text,venue text,start_at timestamptz,end_at timestamptz,status text not null default 'planned',lead_department uuid references departments(id),created_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists meetings(id uuid primary key default gen_random_uuid(),title text not null,meeting_date timestamptz not null,venue text,agenda text,minutes text,status text not null default 'scheduled',created_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists documents(id uuid primary key default gen_random_uuid(),title text not null,document_type text,reference_no text,file_path text,status text not null default 'draft',owner_department uuid references departments(id),uploaded_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists student_concerns(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id),subject text not null,details text not null,category text,status text not null default 'submitted',assigned_to uuid references profiles(id),resolution text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,publish_at timestamptz,expires_at timestamptz,status text not null default 'draft',published_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists finance_transactions(id uuid primary key default gen_random_uuid(),transaction_date date not null default current_date,reference_no text,description text not null,transaction_type text not null,amount numeric(14,2) not null default 0,status text not null default 'pending',department_id uuid references departments(id),created_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists inventory_items(id uuid primary key default gen_random_uuid(),property_no text unique,item_name text not null,category text,quantity integer not null default 1,condition text not null default 'good',location text,custodian uuid references profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists borrowing_requests(id uuid primary key default gen_random_uuid(),item_id uuid references inventory_items(id),requested_by uuid references profiles(id),purpose text,checkout_at timestamptz,expected_return_at timestamptz,returned_at timestamptz,status text not null default 'pending',approved_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists governance_instruments(id uuid primary key default gen_random_uuid(),title text not null,instrument_type text not null,reference_no text,status text not null default 'draft',effective_date date,file_path text,created_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists scorecard_indicators(id uuid primary key default gen_random_uuid(),indicator_code text unique,objective text not null,indicator text not null,target numeric,actual numeric default 0,unit text,status text not null default 'not_started',owner_department uuid references departments(id),updated_at timestamptz not null default now());
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),actor uuid references profiles(id),action text not null,entity_type text,entity_id uuid,metadata jsonb,created_at timestamptz not null default now());
insert into departments(code,name) values ('OES','Office of the Executive Secretary'),('SWE','Department of Student Welfare and Engagement'),('SPPM','Department of Strategic Planning and Performance Management'),('FIN','Department of Finance and Inventory'),('MC','Department of Multimedia and Creatives'),('ERP','Department of External Relations and Partnerships'),('AA','Department of Academic Affairs'),('CASR','Department of Culture, Arts, Sports and Recreation'),('ES','Department of Environment and Sustainability'),('SSGA','Department of Student Services and General Affairs') on conflict(code) do nothing;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.current_role() returns user_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role<>'student' and is_active=true) $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in('super_admin','president','vice_president','executive_secretary') and is_active=true) $$;
alter table departments enable row level security; alter table profiles enable row level security; alter table tasks enable row level security; alter table activities enable row level security; alter table meetings enable row level security; alter table documents enable row level security; alter table student_concerns enable row level security; alter table announcements enable row level security; alter table finance_transactions enable row level security; alter table inventory_items enable row level security; alter table borrowing_requests enable row level security; alter table governance_instruments enable row level security; alter table scorecard_indicators enable row level security; alter table audit_logs enable row level security;
create policy "departments readable" on departments for select to authenticated using(true);
create policy "admin departments" on departments for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "profile self/admin" on profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "admin profiles" on profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "staff tasks" on tasks for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff activities" on activities for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff meetings" on meetings for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff documents" on documents for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff announcements" on announcements for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff inventory" on inventory_items for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff borrowing" on borrowing_requests for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff governance" on governance_instruments for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "staff scorecard" on scorecard_indicators for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "admin audit logs" on audit_logs for select to authenticated using(public.is_admin());
create policy "finance access" on finance_transactions for all to authenticated using(public.current_role() in('super_admin','president','vice_president','executive_secretary','treasurer','auditor')) with check(public.current_role() in('super_admin','president','vice_president','executive_secretary','treasurer'));
create policy "student concern insert" on student_concerns for insert to authenticated with check(student_id=auth.uid());
create policy "student concern read" on student_concerns for select to authenticated using(student_id=auth.uid() or public.is_staff());
create policy "staff concern update" on student_concerns for update to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "published announcements" on announcements for select to anon using(status='published' and (publish_at is null or publish_at<=now()) and (expires_at is null or expires_at>now()));
insert into storage.buckets(id,name,public) values('usg-files','usg-files',false) on conflict(id) do nothing;
create policy "staff file read" on storage.objects for select to authenticated using(bucket_id='usg-files' and public.is_staff());
create policy "staff file upload" on storage.objects for insert to authenticated with check(bucket_id='usg-files' and public.is_staff());
create policy "staff file update" on storage.objects for update to authenticated using(bucket_id='usg-files' and public.is_staff()) with check(bucket_id='usg-files' and public.is_staff());
create policy "admin file delete" on storage.objects for delete to authenticated using(bucket_id='usg-files' and public.is_admin());